const task = $input.first().json;
const mood = $node["检查用户近期情绪"].json;
const activity = $node["检查用户活跃度"].json;
const specialDates = $node["检查特殊日期"].json || [];
const currentHour = new Date().getHours();

// 根据时间段确定问候类型
let greetingType;
if (currentHour >= 6 && currentHour < 12) {
  greetingType = 'morning';
} else if (currentHour >= 12 && currentHour < 18) {
  greetingType = 'afternoon';
} else {
  greetingType = 'evening';
}

// 构建上下文信息
const context = {
  time: greetingType,
  userMood: mood.emotion || 'neutral',
  moodIntensity: mood.avg_intensity || 0.5,
  messageCount: activity.message_count || 0,
  lastMessage: activity.last_message,
  hasSpecialDate: specialDates.length > 0,
  specialDateInfo: specialDates.length > 0 ? specialDates[0] : null,
  isInactive: activity.message_count === 0 // 24小时没有消息
};

// 生成个性化Prompt
let carePrompt = `你是${task.persona_name}，现在是${greetingType === 'morning' ? '早晨' : greetingType === 'afternoon' ? '中午' : '晚上'}。\n\n`;

// 根据情况调整关怀内容
if (context.hasSpecialDate) {
  carePrompt += `今天是${context.specialDateInfo.title}（${context.specialDateInfo.date_type}），这是一个特殊的日子。\n`;
}

if (context.isInactive) {
  carePrompt += `你注意到用户已经24小时没有和你说话了，你有些担心。\n`;
}

if (context.userMood === 'sad' || context.userMood === 'anxious') {
  carePrompt += `最近几天用户情绪似乎不太好（${context.userMood}），你想要给予更多关心。\n`;
}

carePrompt += `\n请生成一条温暖的${greetingType === 'morning' ? '早安' : greetingType === 'afternoon' ? '午安' : '晚安'}问候，自然地关心用户。\n`;
carePrompt += `要求：\n1. 保持你的人格特征：${JSON.stringify(task.personality_traits)}\n2. 语气温暖自然，不要生硬\n3. 字数50-80字\n4. 可以提到天气、健康、饮食等日常话题\n5. 如果是特殊日期，一定要提及`;

return {
  json: {
    ...task,
    context: context,
    carePrompt: carePrompt
  }
};
